nickname":"Olivia","birthday":"2025-09-23T00:00:00Z"},{"family_role_id":"16886181-ca88-4c7b-9783-e31a1cff8f31","role_name":"Noah Carter (Son of Michael & Sarah)","user_id":null,"role_nickname":"Noah","birthday":"2025-09-23T00:00:00Z","preferences":{"dietary":{"allergies":["dairy"],"favorites":["beef"]},"schedule":{"wake_time":"07:00","sleep_time":"23:00"}}},{"family_role_id":"824d21c8-e9d0-409a-910b-dd1773c1f88b","role_name":"Bella (Great-Grandparent)","user_id":null,"role_nickname":"Bella","birthday":"2025-09-23T00:00:00Z"},{"family_role_id":"5f509eed-d4fd-476c-8a72-ccdbe19bdc85","role_name":"Robert Carter (Son of Margaret)","user_id":null,"role_nickname":"Robert","birthday":"2025-09-23T00:00:00Z"},{"family_role_id":"38211834-fd4f-4147-a57e-5762e7642488","role_name":"Linda Carter (Wife of Robert)","user_id":null,"role_nickname":"Linda","birthday":"2025-09-23T00:00:00Z"},{"family_role_id":"086366c2-7845-4412-b430-570fbd08196f","role_name":"Heisenberg (Grandparent)","user_id":"a7a2dfb9-0995-489a-929e-88be06e1bf2f","role_nickname":"Heisenberg","birthday":"1985-03-15T00:00:00Z","preferences":{"dietary":{"allergies":["peanuts","shellfish"],"restrictions":["low-sodium"],"dislikes":["cilantro","liver"],"favorites":["Italian","BBQ","spicy food"]},"schedule":{"wake_time":"06:30","sleep_time":"22:30"}}},{"family_role_id":"0a3f2af0-999f-4d91-a035-3b2c0dbf373d","role_name":"David Wilson (Husband of Emily)","user_id":null,"role_nickname":"David","birthday":"2025-09-23T00:00:00Z"},{"family_role_id":"b80bab36-501f-4445-a667-f396ecdfd00f","role_name":"Michael Carter (Son of Robert & Linda)","user_id":null,"role_nickname":"Michael","birthday":"2025-09-23T00:00:00Z"}],"location":"上海市浦东新区陆家嘴金融中心","locale":"Asia/Shanghai"},"user_brief":{"task":{"task_lists":[{"task_list_id":"626726a9-fe42-4607-ae2d-3128d598bf6a","name":"hello","description":null},{"task_list_id":"8873bb27-0675-4952-afdc-b3ef6e59bc6e","name":"folder2","description":null},{"task_list_id":"f63a1c94-ec0c-4d72-ac74-4f463b3